class Trigger(BaseModel):
    """
    An ongoing trigger: a zone (4.3) or a ward on a creature (hit_by_melee).
    Several events share one roll and one limit ("enters the Emanation or ends
    its turn there ... only once per turn").
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    on: Annotated[
        list[
            Literal[
                "cast",
                "enter",
                "enter_first_time_on_turn",
                "start_turn",
                "end_turn",
                "area_enters_space",
                "within_feet",
                "per_distance_moved",
                "hit_by_melee",
                "casts_spell",
                "attack_hit",
                "caster_turn_start",
                "caster_turn_end",
                "spell_ends",
            ]
        ],
        Field(min_length=1, title="On"),
    ]
    feet: Annotated[int | None, Field(title="Feet")] = None
    once_per: Annotated[Literal["turn", "round", "activation"] | None, Field(title="Once Per")] = None
    optional: Annotated[bool, Field(title="Optional")] = False
    turns: Annotated[list[int], Field(title="Turns")] = []
    requires: Requires | None = None
    attack: Annotated[
        Literal["melee", "ranged", "weapon", "melee_weapon", "ranged_weapon", "spell"] | None, Field(title="Attack")
    ] = None
    only_targets: Annotated[bool, Field(title="Only Targets")] = False
    rolls: Annotated[list[Roll], Field(title="Rolls", validate_default=True)] = []
    applies: Annotated[list[Applies], Field(title="Applies", validate_default=True)] = []


class Variant(BaseModel):
    """
    Another way to cast the same spell. Picking it applies ``patch`` to the base
    and, if ``modes`` is set, replaces the base modes. Use a variant when the pick
    changes what the spell does (Command's commands, Heal's action counts, Circle
    casting); use a CastChoice when the pick only fills in a value (a damage type).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: Annotated[str, Field(title="Id")]
    label: Annotated[str, Field(title="Label")]
    group: Annotated[str | None, Field(title="Group")] = None
    participants: Participants | None = None
    extra_components: Annotated[list[ExtraComponent], Field(title="Extra Components", validate_default=True)] = []
    patch: Annotated[list[Op], Field(title="Patch", validate_default=True)] = []
    modes: Annotated[list[Mode], Field(title="Modes", validate_default=True)] = []
    scaling: Annotated[list[ScalingRule], Field(title="Scaling", validate_default=True)] = []
    ends_if: Annotated[list[str], Field(title="Ends If")] = []


class WhileActive(BaseModel):
    """An effect that lasts only while the condition does ("While Charmed, ...")."""

